import React, { useState } from 'react';
import './CreateCoinflipModal.css';

const CreateCoinflipModal = ({ onClose, userId, socket, setBalance, userInventory }) => {
  const [selectedItems, setSelectedItems] = useState([]);
  const [minOpponentValue, setMinOpponentValue] = useState(0);
  const [maxOpponentValue, setMaxOpponentValue] = useState(100000);
  const [searchTerm, setSearchTerm] = useState('');
  const [rarityFilter, setRarityFilter] = useState('all');
  const [sortBy, setSortBy] = useState('value_desc');
  const [loading, setLoading] = useState(false);

  // Use the passed inventory prop instead of fetching separately
  const inventory = userInventory || [];

  const toggleItemSelection = (item) => {
    const existingIndex = selectedItems.findIndex(si => si.itemId === item.itemId);

    if (existingIndex >= 0) {
      // Remove item
      setSelectedItems(selectedItems.filter((_, index) => index !== existingIndex));
    } else {
      // Add item
      setSelectedItems([...selectedItems, item]);
    }
  };

  const getTotalValue = () => {
    return selectedItems.reduce((sum, item) => sum + (item.value || item.details?.value || 0), 0);
  };

  const handleCreateCoinflip = async () => {
    if (selectedItems.length === 0) {
      alert('Please select at least one item to bet');
      return;
    }

    setLoading(true);

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/coinflip`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          selectedItems: selectedItems.map(item => ({
            itemId: item.itemId,
            quantity: item.quantity || 1,
            value: item.value || item.details?.value || 0
          })),
          minOpponentValue,
          maxOpponentValue
        })
      });

      const data = await response.json();

      if (response.ok) {
        alert('Coinflip created successfully!');

        // Update user balance
        if (setBalance) {
          const totalWagered = getTotalValue();
          setBalance(prev => prev - totalWagered);
        }

        // Notify others
        if (socket) {
          socket.emit('newCoinflip', data);
        }

        onClose();
      } else {
        alert(data.message || 'Failed to create coinflip');
      }
    } catch (error) {
      console.error('Error creating coinflip:', error);
      alert('Error creating coinflip');
    } finally {
      setLoading(false);
    }
  };

  const getRarityClass = (rarity) => {
    switch(rarity) {
      case 'common': return 'rarity-common';
      case 'rare': return 'rarity-rare';
      case 'epic': return 'rarity-epic';
      case 'legendary': return 'rarity-legendary';
      case 'mythic': return 'rarity-mythic';
      default: return 'rarity-common';
    }
  };

  // Filter and sort inventory
  let filteredInventory = [...inventory];

  if (searchTerm) {
    filteredInventory = filteredInventory.filter(item =>
      (item.details?.name || item.name).toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.details?.description || item.description).toLowerCase().includes(searchTerm.toLowerCase())
    );
  }

  if (rarityFilter !== 'all') {
    filteredInventory = filteredInventory.filter(item =>
      (item.details?.rarity || item.rarity) === rarityFilter
    );
  }

  // Sort inventory
  filteredInventory.sort((a, b) => {
    switch(sortBy) {
      case 'value_asc':
        return (a.value || a.details?.value || 0) - (b.value || b.details?.value || 0);
      case 'value_desc':
        return (b.value || b.details?.value || 0) - (a.value || a.details?.value || 0);
      case 'name_asc':
        return (a.details?.name || a.name).localeCompare(b.details?.name || b.name);
      case 'name_desc':
        return (b.details?.name || b.name).localeCompare(a.details?.name || a.name);
      default:
        return (b.value || b.details?.value || 0) - (a.value || a.details?.value || 0);
    }
  });

  if (loading) {
    return (
      <div className="modal-overlay" onClick={onClose}>
        <div className="modal" onClick={(e) => e.stopPropagation()}>
          <div className="modal-header">
            <h2>Create Coinflip Game</h2>
            <button className="close-modal" onClick={onClose}>×</button>
          </div>
          <div className="loading-container">
            <div className="loading-spinner"></div>
            <p>Loading...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal enhanced" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Create Coinflip Game</h2>
          <button className="close-modal" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          <div className="form-group">
            <label className="form-label">Opponent Value Range</label>
            <div className="range-inputs">
              <input
                type="number"
                className="form-control"
                placeholder="Min value"
                value={minOpponentValue}
                onChange={(e) => setMinOpponentValue(Number(e.target.value))}
                min="0"
              />
              <span>to</span>
              <input
                type="number"
                className="form-control"
                placeholder="Max value"
                value={maxOpponentValue}
                onChange={(e) => setMaxOpponentValue(Number(e.target.value))}
                min={minOpponentValue}
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Selected Items: {getTotalValue().toLocaleString()} AMP</label>
            <div className="selected-items">
              {selectedItems.length > 0 ? (
                selectedItems.map((item, index) => (
                  <div key={`${item.itemId}-${index}`} className="selected-item">
                    <img 
                      src={item.details?.imageUrl || item.image || '/default-item.png'} 
                      alt={item.details?.name || item.name} 
                      className="item-image"
                      onError={(e) => {
                        e.target.src = '/default-item.png';
                      }}
                    />
                    <div className="item-info">
                      <div className="item-name">{item.details?.name || item.name}</div>
                      <div className="item-value">{(item.value || item.details?.value || 0).toLocaleString()} AMP</div>
                    </div>
                    <button 
                      className="remove-item-btn"
                      onClick={() => toggleItemSelection(item)}
                    >
                      ×
                    </button>
                  </div>
                ))
              ) : (
                <div className="no-selected-items">
                  <p>No items selected</p>
                </div>
              )}
            </div>
          </div>

          <div className="inventory-filters">
            <input
              type="text"
              className="form-control"
              placeholder="Search items..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <select 
              className="form-control" 
              value={rarityFilter}
              onChange={(e) => setRarityFilter(e.target.value)}
            >
              <option value="all">All Rarities</option>
              <option value="common">Common</option>
              <option value="uncommon">Uncommon</option>
              <option value="rare">Rare</option>
              <option value="epic">Epic</option>
              <option value="legendary">Legendary</option>
              <option value="mythic">Mythic</option>
            </select>
            <select 
              className="form-control" 
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
            >
              <option value="value_desc">Value: High to Low</option>
              <option value="value_asc">Value: Low to High</option>
              <option value="name_asc">Name: A to Z</option>
              <option value="name_desc">Name: Z to A</option>
            </select>
          </div>

          <div className="inventory-grid">
            {filteredInventory.length > 0 ? (
              filteredInventory.map((item) => {
                const isSelected = selectedItems.some(si => si.itemId === item.itemId);
                return (
                  <div 
                    key={item.itemId || item.id} 
                    className={`inventory-item ${isSelected ? 'selected' : ''}`}
                    onClick={() => toggleItemSelection(item)}
                  >
                    <img 
                      src={item.details?.imageUrl || item.image || '/default-item.png'} 
                      alt={item.details?.name || item.name} 
                      className="item-image"
                      onError={(e) => {
                        e.target.src = '/default-item.png';
                      }}
                    />
                    <div className="item-info">
                      <div className="item-name">{item.details?.name || item.name}</div>
                      <div className="item-value">{(item.value || item.details?.value || 0).toLocaleString()} AMP</div>
                      <span className={`badge ${getRarityClass(item.details?.rarity || item.rarity)}`}>
                        {(item.details?.rarity || item.rarity)}
                      </span>
                    </div>
                  </div>
                );
              })
            ) : (
              <div className="no-inventory-items">
                <p>No items available in your inventory</p>
              </div>
            )}
          </div>
        </div>

        <div className="modal-actions">
          <button className="btn btn-secondary" onClick={onClose} disabled={loading}>
            Cancel
          </button>
          <button 
            className="btn btn-primary" 
            onClick={handleCreateCoinflip}
            disabled={selectedItems.length === 0 || loading}
          >
            {loading ? 'Creating...' : `Create Game (${getTotalValue().toLocaleString()} AMP)`}
          </button>
        </div>
      </div>
    </div>
  );
};

export default CreateCoinflipModal;
